// Life-skills stories: short picture stories about things that really happen to a 3-8 year old (a toy
// a little cousin wants, a cup that breaks, losing a race, a new child at school, the dark at bedtime).
// A child understands a feeling much better inside a story than from a rule, so each story:
//   1. tells the moment (one short sentence per picture, read aloud, Next button),
//   2. stops and asks "What should Kabir do?" — every answer gets its consequence and the WHY, a wrong
//      choice is never "wrong!", just "what might happen?", and the child tries again,
//   3. shows how it ends, names the big idea and why it matters, checks it was understood,
//   4. gives a small "try it today" mission with the child's name ("I did it!" goes to the learning graph).
// English, Hindi and Hinglish; other languages fall back to English like the rest of the subject content.
import type { Text } from "../i18n";

export interface StoryPage { scene: string; text: Text }
export interface StoryOption { text: Text; good: boolean; then: Text }
export interface Story {
  id: string;
  icon: string;
  title: Text;
  skill: Text;
  ages: [number, number];
  pages: StoryPage[];
  ask: Text;
  options: StoryOption[];
  after: StoryPage[];
  bigIdea: Text;
  why: Text;
  check: { q: Text; a: Text; others: Text[] };
  tryToday: Text; // {name} = the child's name
}

const T = (en: string, hi: string, hinglish: string): Text => ({ en, hi, hinglish });
const P = (scene: string, en: string, hi: string, hinglish: string): StoryPage => ({ scene, text: T(en, hi, hinglish) });
const O = (good: boolean, text: Text, then: Text): StoryOption => ({ good, text, then });

